(30,'tools/diagnostics','Diagnostics','Tools',10,'<?php\n$pdo = DB::conn();\n\necho \"<h1>Diagnostics</h1>\";\n\n// Filters\n$level = $_GET[\"level\"] ?? \"\";\n$limit = (int)($_GET[\"limit\"] ?? 100);\nif ($limit <= 0 || $limit > 1000) $limit = 100;\n\n$where = \"\";\n$params = [];\nif (in_array($level, [\"INFO\",\"WARN\",\"ERROR\"])) {\n    $where = \"WHERE level = ?\";\n    $params[] = $level;\n}\n\n// Fetch logs\n$sql = \"SELECT id, created_at, level, message FROM diagnostics \" . $where . \" ORDER BY id DESC LIMIT ?\";\n$stmt = $pdo->prepare($sql);\nforeach ($params as $idx => $val) {\n    $stmt->bindValue($idx+1, $val);\n}\n$stmt->bindValue(count($params)+1, $limit, PDO::PARAM_INT);\n$stmt->execute();\n\necho \"<form method=\\\"get\\\">\n  <input type=\\\"hidden\\\" name=\\\"page\\\" value=\\\"tools/diagnostics\\\">\n  Level: \n  <select name=\\\"level\\\">\n    <option value=\\\"\\\">(All)</option>\n    <option value=\\\"INFO\\\" \".($level===\"INFO\"?\"selected\":\"\").\">INFO</option>\n    <option value=\\\"WARN\\\" \".($level===\"WARN\"?\"selected\":\"\").\">WARN</option>\n    <option value=\\\"ERROR\\\" \".($level===\"ERROR\"?\"selected\":\"\").\">ERROR</option>\n  </select>\n  Limit: <input name=\\\"limit\\\" value=\\\"\".$limit.\"\\\" size=\\\"4\\\">\n  <button type=\\\"submit\\\">Apply</button>\n</form>\";\n\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>ID</th>\n  <th>Time</th>\n  <th>Level</th>\n  <th>Message</th>\n</tr>\";\n\nforeach ($stmt as $row) {\n    echo \"<tr>\n      <td>\".$row[\"id\"].\"</td>\n      <td>\".$row[\"created_at\"].\"</td>\n      <td>\".$row[\"level\"].\"</td>\n      <td><pre style=\\\"margin:0;white-space:pre-wrap;\\\">\".htmlspecialchars($row[\"message\"]).\"</pre></td>\n    </tr>\";\n}\necho \"</table>\";\n\n// Quick self-test: log an INFO message (optional button)\nif ($_SERVER[\"REQUEST_METHOD\"] === \"POST\" && isset($_POST[\"self_test\"])) {\n    try {\n        $log = $pdo->prepare(\"INSERT INTO diagnostics (level, message) VALUES (?, ?)\");\n        $log->execute([\"INFO\", \"Self-test: diagnostics page is working\"]);\n        echo \"<p style=\\\"color:green;\\\">Self-test log inserted.</p>\";\n    } catch (Exception $e) {\n        echo \"<p style=\\\"color:red;\\\">Self-test failed: \".htmlspecialchars($e->getMessage()).\"</p>\";\n    }\n}\necho \"<form method=\\\"post\\\"><button name=\\\"self_test\\\" value=\\\"1\\\">Insert self-test log</button></form>\";\n;?>','diagnostics'),
