(31,'parties/master','Party Master','Parties',1,'<?php\n$pdo = DB::conn();\n\nif ($_SERVER[\"REQUEST_METHOD\"] === \"POST\") {\n    try {\n        $stmt = $pdo->prepare(\"INSERT INTO parties (name, gstin, party_type, city, state, state_code) VALUES (?,?,?,?,?,?)\");\n        $stmt->execute([\n            $_POST[\"name\"],\n            $_POST[\"gstin\"] ?: null,\n            $_POST[\"party_type\"],\n            $_POST[\"city\"] ?: null,\n            $_POST[\"state\"] ?: null,\n            $_POST[\"state_code\"] ?: null\n        ]);\n        echo \"<p style=\"color:green;\">Party saved successfully.</p>\";\n    } catch (Exception $e) {\n        echo \"<p style=\"color:red;\">Error: \".htmlspecialchars($e->getMessage()).\"</p>\";\n    }\n}\n\necho \"<h1>Party Master</h1>\";\necho \"<form method=post>\n  <label>Name: <input name=name required></label><br>\n  <label>GSTIN: <input name=gstin maxlength=15></label><br>\n  <label>Type: \n    <select name=party_type>\n      <option value=\"customer\">Customer</option>\n      <option value=\"supplier\">Supplier</option>\n      <option value=\"both\">Both</option>\n    </select>\n  </label><br>\n  <label>City: <input name=city></label><br>\n  <label>State: <input name=state></label><br>\n  <label>State Code: <input name=state_code maxlength=2></label><br>\n  <button type=submit>Save</button>\n</form>\";\n\necho \"<h2>Existing Parties</h2>\";\n$stmt = $pdo->query(\"SELECT id, name, gstin, party_type, city, state, state_code FROM parties ORDER BY id DESC LIMIT 20\");\necho \"<table border=1 cellpadding=6><tr><th>ID</th><th>Name</th><th>GSTIN</th><th>Type</th><th>City</th><th>State</th><th>Code</th></tr>\";\nforeach ($stmt as $row) {\n    echo \"<tr>\n        <td>{$row[\"id\"]}</td>\n        <td>\".htmlspecialchars($row[\"name\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"gstin\"]).\"</td>\n        <td>{$row[\"party_type\"]}</td>\n        <td>\".htmlspecialchars($row[\"city\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"state\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"state_code\"]).\"</td>\n    </tr>\";\n}\necho \"</table>\";\n;?>','parties'),
