(38,'tools/gst-summary','GST Summary','Tools',5,'<?php\n$pdo = DB::conn();\n\necho \"<h1>GST Summary</h1>\";\n\n$sql = \"SELECT \n            DATE_FORMAT(i.invoice_date, \'%Y-%m\') AS period,\n            SUM(it.taxable_amount) AS taxable_value,\n            SUM(it.cgst_amount) AS cgst_total,\n            SUM(it.sgst_amount) AS sgst_total,\n            SUM(it.igst_amount) AS igst_total,\n            SUM(it.line_total) AS grand_total\n        FROM invoices i\n        JOIN invoice_items it ON i.id = it.invoice_id\n        WHERE i.status <> \'cancelled\'\n        GROUP BY DATE_FORMAT(i.invoice_date, \'%Y-%m\')\n        ORDER BY period DESC\";\n\n$stmt = $pdo->query($sql);\n\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>Period (YYYY-MM)</th>\n  <th>Taxable Value</th>\n  <th>CGST</th>\n  <th>SGST</th>\n  <th>IGST</th>\n  <th>Grand Total</th>\n</tr>\";\n\nforeach ($stmt as $row) {\n    echo \"<tr>\n        <td>{$row[\"period\"]}</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"taxable_value\"],2).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"cgst_total\"],2).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"sgst_total\"],2).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"igst_total\"],2).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"grand_total\"],2).\"</td>\n    </tr>\";\n}\necho \"</table>\";\n;?>','invoices,invoice_items');
