(4,'invoices/list','List Invoices','Invoices',2,'<?php\n$pdo = DB::conn();\necho \"<h1>Invoices</h1>\";\n\n$sql = \"SELECT i.id, i.invoice_no, i.invoice_date, i.party_name, i.inv_type, i.status,\n               COALESCE(SUM(it.line_total),0) AS total\n        FROM invoices i\n        LEFT JOIN invoice_items it ON i.id = it.invoice_id\n        GROUP BY i.id, i.invoice_no, i.invoice_date, i.party_name, i.inv_type, i.status\n        ORDER BY i.invoice_date DESC, i.id DESC\n        LIMIT 50\";\n\n$stmt = $pdo->query($sql);\n\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>ID</th>\n  <th>No</th>\n  <th>Date</th>\n  <th>Party</th>\n  <th>Type</th>\n  <th>Status</th>\n  <th>Total</th>\n</tr>\";\n\nforeach ($stmt as $row) {\n    echo \"<tr>\n        <td>{$row[\"id\"]}</td>\n        <td>\".htmlspecialchars($row[\"invoice_no\"]).\"</td>\n        <td>{$row[\"invoice_date\"]}</td>\n        <td>\".htmlspecialchars($row[\"party_name\"]).\"</td>\n        <td>{$row[\"inv_type\"]}</td>\n        <td>{$row[\"status\"]}</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"total\"],2).\"</td>\n    </tr>\";\n}\necho \"</table>\";\n;?>','invoices,invoice_items'),
